uth_example:
docs = {
    "How to reset a password": [0.9, 0.1, 0.2],
    "Monthly billing explained": [0.1, 0.8, 0.3],
    "Password rules and length": [0.7, 0.0, 0.6],
}
query = [0.8, 0.05, 0.3]                 # "forgot my password"

def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = sum(x * x for x in a) ** 0.5
    nb = sum(y * y for y in b) ** 0.5
    return round(dot / (na * nb), 4)

scores = {title: cosine(query, vec) for title, vec in docs.items()}
ranked = sorted(scores.items(), key=lambda kv: kv[1], reverse=True)
for title, score in ranked:
    print(f"{score}  {title}")
context = ranked[0][0]
print("send to the LLM:", context)
